const CACHE='marvel-watchlist-v4';
const ASSETS=['./','./index.html','./styles.css','./app.js','./data.js','./doomsday-data.js','./manifest.webmanifest','./icon-192.png','./icon-512.png','./icon.svg','./art-avengers.webp','./art-xmen.webp','./art-spider.webp','./art-fantastic-four.webp','./doom-portrait.jpg','./doom-scene.jpg','./doom-comic-cover.jpg','./doom-comic-panel.webp','./marvel-watchlist-offline.zip'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response}).catch(()=>caches.match(event.request)))});
